try:
    print('>>> f = pow')
    print('>>> x = []')
    print('>>> y = slice(0)')
    print('>>> f(x, y)')
    f = pow
    x = []
    y = slice(0)
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
